"use strict";(self.webpackChunkblog=self.webpackChunkblog||[]).push([[130],{7735:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2026/04/26/effectScope","metadata":{"permalink":"/blog/2026/04/26/effectScope","source":"@site/blog/2026-04-26/effectScope.md","title":"Vue3\u6e90\u7801\u89e3\u6790\u4e4beffectScope","description":"effectScope","date":"2026-04-26T00:00:00.000Z","tags":[],"readingTime":5.62,"hasTruncateMarker":false,"authors":[],"frontMatter":{},"unlisted":false,"nextItem":{"title":"\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b","permalink":"/blog/2025/12/01/\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b"}},"content":"## effectScope\\r\\n\\r\\neffectScope \u662f Vue 3 \u63d0\u4f9b\u7684\u7528\u4e8e\u7ba1\u7406\u4e00\u7ec4\u54cd\u5e94\u5f0f\u526f\u4f5c\u7528\u7684\u5de5\u5177\uff0c\u662f Vue 3.2 \u5f15\u5165\u7684\u6838\u5fc3 API\uff0c\u7528\u4e8e\u521b\u5efa\u526f\u4f5c\u7528\u4f5c\u7528\u57df\u5bb9\u5668\uff0c\u5b98\u7f51\u63cf\u8ff0\u4e3a\u521b\u5efa\u4e00\u4e2a effect \u4f5c\u7528\u57df\uff0c\u53ef\u4ee5\u6355\u83b7\u5176\u4e2d\u6240\u521b\u5efa\u7684\u54cd\u5e94\u5f0f\u526f\u4f5c\u7528 (\u5373\u8ba1\u7b97\u5c5e\u6027\u548c\u4fa6\u542c\u5668)\uff0c\u8fd9\u6837\u6355\u83b7\u5230\u7684\u526f\u4f5c\u7528\u53ef\u4ee5\u4e00\u8d77\u5904\u7406 123\u3002\\r\\n\\r\\n\u5b83\u5141\u8bb8\u5c06\u591a\u4e2a\u54cd\u5e94\u5f0f\u526f\u4f5c\u7528\uff08\u4f8b\u5982 computed\u3001watch\u3001onMounted \u7b49\uff09\u7ec4\u5408\u5230\u4e00\u4e2a\u4f5c\u7528\u57df\u4e2d\uff0c\u5e76\u5728\u9700\u8981\u65f6\u4e00\u8d77\u505c\u6b62\u5b83\u4eec\uff0c\u80fd\u591f\u5c06\u591a\u4e2a\u54cd\u5e94\u5f0f\u526f\u4f5c\u7528\uff08\u5982 watch\u3001watchEffect \u548c computed\uff09\u7ec4\u7ec7\u5728\u4e00\u8d77\uff0c\u5b9e\u73b0\u7edf\u4e00\u7684\u751f\u547d\u5468\u671f\u7ba1\u7406\\r\\n\\r\\n\u4e0b\u9762\u662f\u53c2\u8003\u4f8b\u5b50\\r\\n\\r\\n### \u4ee3\u7801\\r\\n\\r\\n``` javascript\\r\\n<template>\\r\\n  <div class=\\"hello\\">\\r\\n    <p>{{ count }}</p>\\r\\n    <button @click=\\"inc\\">\u589e\u52a0</button>\\r\\n    <button @click=\\"stopScope\\">\u505c\u6b62 effectScope</button>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport { effectScope, ref, watch } from \'vue\'\\r\\n\\r\\nconst scope = effectScope()\\r\\nconst count = ref(0)\\r\\n\\r\\nscope.run(() => {\\r\\n  watch(count, (val) => {\\r\\n    console.log(\'count changed:\', val)\\r\\n  })\\r\\n})\\r\\n\\r\\nfunction inc() {\\r\\n  count.value++\\r\\n}\\r\\n\\r\\nfunction stopScope() {\\r\\n  scope.stop()\\r\\n}\\r\\n<\/script>\\r\\n```\\r\\n\\r\\n### \u4f8b\u5b50\\r\\n\u5148\u70b9\u51fb\u56db\u4e0b\u589e\u52a0\uff0c\u9875\u9762\u6570\u636e\u540c\u6b65\u66f4\u65b0\uff0c\u70b9\u51fb\u505c\u6b62 effectScope\u540e\u518d\u70b9\u51fb\u56db\u4e0b\u589e\u52a0\uff0c\u9875\u9762\u6570\u636e\u4e0d\u66f4\u65b0\\r\\n![effectSCope\u4f8b\u5b50](./images/effectSCope\u4f8b\u5b50.png)\\r\\n\\r\\n## onSCopeDispose\\r\\nonScopeDispose \u662f Vue 3 \u4e2d\u7528\u4e8e\u7ba1\u7406\u54cd\u5e94\u5f0f\u526f\u4f5c\u7528\u7684\u4e00\u4e2a\u91cd\u8981 API\uff0c\u4e3b\u8981\u7528\u4e8e\u5728\u5f53\u524d\u6d3b\u8dc3\u7684 effect \u4f5c\u7528\u57df\u4e0a\u6ce8\u518c\u4e00\u4e2a\u5904\u7406\u56de\u8c03\u51fd\u6570\u3002\u5f53\u8fd9\u4e2a\u4f5c\u7528\u57df\u505c\u6b62\u65f6\uff0c\u6240\u6ce8\u518c\u7684\u56de\u8c03\u51fd\u6570\u4f1a\u88ab\u8c03\u7528\u3002\\r\\n\\r\\n### \u4ee3\u7801\\r\\n``` javascript\\r\\n<template>\\r\\n  <div class=\\"hello\\">\\r\\n    <p>{{ count }}</p>\\r\\n    <button @click=\\"inc\\">\u589e\u52a0</button>\\r\\n    <button @click=\\"stopScope\\">\u505c\u6b62 effectScope</button>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport { effectScope, ref, watch } from \'vue\'\\r\\n\\r\\nimport { onScopeDispose } from \'vue\'\\r\\n\\r\\nconst scope = effectScope()\\r\\nconst count = ref(0)\\r\\n\\r\\nscope.run(() => {\\r\\n  watch(count, (val) => {\\r\\n    console.log(\'count changed:\', val)\\r\\n  })\\r\\n\\r\\n  onScopeDispose(() => {\\r\\n    console.log(\'effectScope \u5df2\u88ab\u9500\u6bc1\')\\r\\n  })\\r\\n})\\r\\n\\r\\nfunction inc() {\\r\\n  count.value++\\r\\n}\\r\\n\\r\\nfunction stopScope() {\\r\\n  scope.stop()\\r\\n}\\r\\n<\/script>\\r\\n```\\r\\n\\r\\n### \u6548\u679c\u56fe\\r\\n\\r\\n\u5148\u70b9\u51fb\u56db\u4e0b\u589e\u52a0\uff0c\u9875\u9762\u6570\u636e\u540c\u6b65\u66f4\u65b0\uff0c\u70b9\u51fb\u505c\u6b62 effectScope\u540e\u518d\u70b9\u51fb\u56db\u4e0b\u589e\u52a0\uff0c\u9875\u9762\u6570\u636e\u4e0d\u66f4\u65b0\\r\\n\\r\\n![onScopeDispose\u4f8b\u5b50](./images/onScopeDispose\u4f8b\u5b50.png)\\r\\n\\r\\n\\r\\n\\r\\n## \u4f7f\u7528\u573a\u666f\\r\\n\\r\\n- **\u6784\u5efa\u81ea\u6e05\u6d01\u7684\u7ec4\u5408\u5f0f\u51fd\u6570**\\r\\n\\r\\n\u5728\u81ea\u5b9a\u4e49\u7ec4\u5408\u5f0f\u51fd\u6570\u4e2d\uff0c\u53ef\u80fd\u4f1a\u521b\u5efa\u4e00\u4e9b\u526f\u4f5c\u7528\uff0c\u5982\u5b9a\u65f6\u5668\u3001\u4e8b\u4ef6\u76d1\u542c\u5668\u7b49\u3002\u4f7f\u7528 `effectScope` \u548c `onScopeDispose` \u53ef\u4ee5\u786e\u4fdd\u5728\u7ec4\u5408\u5f0f\u51fd\u6570\u4e0d\u518d\u4f7f\u7528\u65f6\uff0c\u8fd9\u4e9b\u526f\u4f5c\u7528\u80fd\u591f\u88ab\u6b63\u786e\u6e05\u7406\uff0c\u907f\u514d\u5185\u5b58\u6cc4\u6f0f\u3002\\r\\n\\r\\n- **\u4e0e\u7ec4\u4ef6\u751f\u547d\u5468\u671f\u65e0\u7f1d\u96c6\u6210**\\r\\n\\r\\n\u5728\u7ec4\u4ef6\u4e2d\uff0c\u53ef\u4ee5\u4f7f\u7528 `effectScope` \u548c `onScopeDispose` \u6765\u7ba1\u7406\u7ec4\u4ef6\u5185\u90e8\u7684\u526f\u4f5c\u7528\u3002\u5f53\u7ec4\u4ef6\u5378\u8f7d\u65f6\uff0c\u4f5c\u7528\u57df\u4f1a\u81ea\u52a8\u505c\u6b62\uff0c\u6240\u6709\u901a\u8fc7 `onScopeDispose` \u6ce8\u518c\u7684\u6e05\u7406\u51fd\u6570\u4f1a\u88ab\u6267\u884c\u3002\\r\\n\\r\\n- **\u521b\u5efa\u53ef\u590d\u7528\u7684\u975e\u7ec4\u4ef6\u903b\u8f91\u6a21\u5757**\\r\\n\\r\\n\u53ef\u4ee5\u4f7f\u7528 `effectScope` \u6765\u5c01\u88c5\u4e00\u4e9b\u53ef\u590d\u7528\u7684\u975e\u7ec4\u4ef6\u903b\u8f91\uff0c\u8fd9\u4e9b\u903b\u8f91\u53ef\u4ee5\u5728\u4e0d\u540c\u7684\u7ec4\u4ef6\u4e2d\u4f7f\u7528\uff0c\u5e76\u4e14\u80fd\u591f\u72ec\u7acb\u7ba1\u7406\u81ea\u5df1\u7684\u526f\u4f5c\u7528\u3002\u50cf\u5728onScopeDispose\u53d6\u6d88\u63a5\u53e3\\r\\n\\r\\n\\r\\n\\r\\n## \u6ce8\u610f\u4e8b\u9879\\r\\n\\r\\n### `effectScope`\\r\\n\\r\\n- **\u5d4c\u5957\u4f5c\u7528\u57df\u7ba1\u7406**\uff1a\u5728\u5d4c\u5957\u7684 `effectScope` \u4e2d\uff0c\u5b50\u4f5c\u7528\u57df\u7684\u751f\u547d\u5468\u671f\u4f9d\u8d56\u4e8e\u7236\u4f5c\u7528\u57df\u3002\u5f53\u7236\u4f5c\u7528\u57df\u505c\u6b62\u65f6\uff0c\u5b50\u4f5c\u7528\u57df\u4e5f\u4f1a\u505c\u6b62\u3002\u8981\u786e\u4fdd\u6b63\u786e\u7ba1\u7406\u5d4c\u5957\u4f5c\u7528\u57df\u7684\u751f\u547d\u5468\u671f\uff0c\u907f\u514d\u51fa\u73b0\u610f\u5916\u7684\u526f\u4f5c\u7528\u6e05\u7406\u95ee\u9898\u3002\\r\\n- **detached \u9009\u9879**\uff1a`effectScope` \u7684 `detached` \u9009\u9879\u7528\u4e8e\u521b\u5efa\u4e00\u4e2a\u72ec\u7acb\u4e8e\u7236\u4f5c\u7528\u57df\u7684\u4f5c\u7528\u57df\u3002\u5f53\u8bbe\u7f6e\u4e3a `true` \u65f6\uff0c\u7236\u4f5c\u7528\u57df\u7684\u505c\u6b62\u4e0d\u4f1a\u5f71\u54cd\u5b50\u4f5c\u7528\u57df\u3002\u4f46\u8981\u6ce8\u610f\uff0c\u9700\u8981\u624b\u52a8\u7ba1\u7406\u8be5\u4f5c\u7528\u57df\u7684\u505c\u6b62\uff0c\u5426\u5219\u53ef\u80fd\u4f1a\u5bfc\u81f4\u5185\u5b58\u6cc4\u6f0f\u3002\\r\\n- **\u83b7\u53d6\u5f53\u524d\u4f5c\u7528\u57df**\uff1a\u4f7f\u7528 `getCurrentScope` \u53ef\u4ee5\u83b7\u53d6\u5f53\u524d\u6d3b\u8dc3\u7684 `effectScope` \u5b9e\u4f8b\uff0c\u5e38\u7528\u4e8e\u5d4c\u5957\u4f5c\u7528\u57df\u4e2d\u83b7\u53d6\u7236\u7ea7\u4f5c\u7528\u57df\u5f15\u7528\u3002\u4f46\u8981\u786e\u4fdd\u5728 `effectScope` \u7684 `run` \u65b9\u6cd5\u5185\u90e8\u8c03\u7528\uff0c\u5426\u5219\u53ef\u80fd\u4f1a\u8fd4\u56de `null` \\r\\n\\r\\n### `onScopeDispose`\\r\\n\\r\\n- **\u6ce8\u518c\u65f6\u673a**\uff1a`onScopeDispose` \u5fc5\u987b\u5728 `effectScope` \u7684 `run` \u65b9\u6cd5\u5185\u90e8\u8c03\u7528\uff0c\u624d\u80fd\u6b63\u786e\u6ce8\u518c\u6e05\u7406\u51fd\u6570\u3002\u5982\u679c\u5728\u4f5c\u7528\u57df\u5916\u90e8\u8c03\u7528\uff0c\u6e05\u7406\u51fd\u6570\u5c06\u4e0d\u4f1a\u5728\u4f5c\u7528\u57df\u505c\u6b62\u65f6\u6267\u884c\u3002\\r\\n- **\u6e05\u7406\u51fd\u6570\u987a\u5e8f**\uff1a\u5728\u540c\u4e00\u4e2a\u4f5c\u7528\u57df\u4e2d\uff0c\u591a\u4e2a `onScopeDispose` \u6ce8\u518c\u7684\u6e05\u7406\u51fd\u6570\u5c06\u6309\u7167\u6ce8\u518c\u7684\u987a\u5e8f\u9006\u5e8f\u6267\u884c\u3002\u786e\u4fdd\u6e05\u7406\u51fd\u6570\u4e4b\u95f4\u4e0d\u4f1a\u76f8\u4e92\u4f9d\u8d56\uff0c\u907f\u514d\u51fa\u73b0\u610f\u5916\u7684\u6e05\u7406\u987a\u5e8f\u95ee\u9898\u3002\\r\\n- **\u5f02\u6b65\u64cd\u4f5c\u6e05\u7406**\uff1a\u5bf9\u4e8e\u5f02\u6b65\u64cd\u4f5c\uff0c\u5982 `Promise` \u6216 `async/await`\uff0c\u8981\u786e\u4fdd\u5728\u6e05\u7406\u51fd\u6570\u4e2d\u5904\u7406\u597d\u672a\u5b8c\u6210\u7684\u5f02\u6b65\u4efb\u52a1\uff0c\u907f\u514d\u51fa\u73b0\u5185\u5b58\u6cc4\u6f0f\u6216\u672a\u5904\u7406\u7684\u9519\u8bef\u3002\\r\\n\\r\\n\\r\\n\\r\\n## \u53ef\u80fd\u51fa\u73b0\u7684\u95ee\u9898\\r\\n\\r\\n- effectScopd\u4e2drun()\u548cstop()\u6ca1\u6709\u914d\u5bf9\u4f7f\u7528\uff0c\u53ef\u80fd\u4f1a\u5bfc\u81f4\u5185\u5b58\u6cc4\u6f0f\u7684\u95ee\u9898\\r\\n- \u907f\u514d\u6ee5\u7528\uff0c\u7b80\u5355\u7684\u7ec4\u4ef6\u4e2deffectWatch\u5df2\u80fd\u6ee1\u8db3\u8981\u6c42"},{"id":"/2025/12/01/\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b","metadata":{"permalink":"/blog/2025/12/01/\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b","source":"@site/blog/2025-12-01/\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b.md","title":"\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b","description":"\u5b9e\u73b0\u539f\u7406","date":"2025-12-01T00:00:00.000Z","tags":[],"readingTime":2.44,"hasTruncateMarker":false,"authors":[],"frontMatter":{},"unlisted":false,"prevItem":{"title":"Vue3\u6e90\u7801\u89e3\u6790\u4e4beffectScope","permalink":"/blog/2026/04/26/effectScope"},"nextItem":{"title":"\u51fd\u6570\u5f0f\u8c03\u7528\u5f39\u7a97\u7ec4\u4ef6","permalink":"/blog/2025/03/29/\u5f39\u7a97\u8c03\u7528"}},"content":"## \u5b9e\u73b0\u539f\u7406\\r\\n\\r\\n**\u5229\u7528Intersection Observer API\u76d1\u542c\u56fe\u7247\u662f\u5426\u8fdb\u5165\u89c6\u53e3\uff0c\u914d\u5408\u81ea\u5b9a\u4e49\u6307\u4ee4v-lazyload\u5b9e\u73b0\u89e3\u8026\u4e0e\u590d\u7528\uff0c\u5e76\u901a\u8fc7placeholder\u548cerror\u5904\u7406\u63d0\u5347\u7528\u6237\u4f53\u9a8c**\u3002\\r\\n\\r\\n## \u5b9e\u73b0\u6b65\u9aa4\\r\\n\\r\\n1. \u521b\u5efa\u6307\u4ee4\u6587\u4ef6directives/lazyload.js\\r\\n2. \u6307\u4ee4\u6838\u5fc3\u751f\u547d\u5468\u671f\uff1a\u5728mounted\u94a9\u5b50\u4e2d\u521d\u59cb\u5316\u89c2\u5bdf\uff0c\u5728unmounted\u94a9\u5b50\u4e2d\u505c\u6b62\u89c2\u5bdf\u3002\\r\\n3. \u6307\u4ee4\u503c (value)\uff1a\u7528\u4e8e\u63a5\u6536\u56fe\u7247\u7684\u771f\u5b9e URL\u3002\\r\\n4. \u5360\u4f4d\u56fe\u4e0e\u9519\u8bef\u5904\u7406\uff1a\u4f7f\u7528\u672c\u5730\u6216\u7edf\u4e00\u7684\u4f4e\u8d28\u91cf\u5360\u4f4d\u56fe\uff08LQIP\uff09\uff0c\u5e76\u76d1\u542c\u56fe\u7247\u7684error\u4e8b\u4ef6\u3002\\r\\n\\r\\n## \u4ee3\u7801\u793a\u4f8b\\r\\n\\r\\n\u81ea\u5b9a\u4e49\u6307\u4ee4lazyload.js\\r\\n\\r\\n```javascript\\r\\nimport defaultImage  from  \'../../public/img/default.png\'\\r\\nimport errorImage  from \'../../public/img/error.png\'\\r\\n \\r\\nexport const lazyLoadDirective = {\\r\\n  mounted(el, binding) {\\r\\n    // 1. \u4f7f\u7528 Intersection Observer\\r\\n    const observer = new IntersectionObserver((entries) => {\\r\\n      entries.forEach(entry => {\\r\\n        // 2. \u5224\u65ad\u662f\u5426\u8fdb\u5165\u89c6\u53e3\\r\\n        if (entry.isIntersecting) {\\r\\n          // 3. \u8fdb\u5165\u89c6\u53e3\u540e\uff0c\u5f00\u59cb\u52a0\u8f7d\u771f\u5b9e\u56fe\u7247\\r\\n          const img = new Image();\\r\\n          img.src = binding.value; // \u6307\u4ee4\u7ed1\u5b9a\u7684\u503c\uff0c\u5373\u771f\u5b9e\u56fe\u7247URL\\r\\n \\r\\n          // 4. \u56fe\u7247\u52a0\u8f7d\u6210\u529f\\r\\n          img.onload = () => {\\r\\n            el.src = binding.value; // \u5c06\u771f\u5b9e\u56fe\u7247URL\u8bbe\u7f6e\u7ed9img\u6807\u7b7e\u7684src\\r\\n            observer.unobserve(el); // \u505c\u6b62\u89c2\u5bdf\u8be5\u5143\u7d20\uff08\u5df2\u52a0\u8f7d\uff0c\u65e0\u9700\u518d\u89c2\u5bdf\uff09\\r\\n          };\\r\\n \\r\\n          // 5. \u56fe\u7247\u52a0\u8f7d\u5931\u8d25\\r\\n          img.onerror = () => {\\r\\n            el.src = errorImage;\\r\\n          };\\r\\n \\r\\n          observer.unobserve(el); // \u65e0\u8bba\u5982\u4f55\uff0c\u505c\u6b62\u89c2\u5bdf\\r\\n        }\\r\\n      });\\r\\n    }, {\\r\\n      rootMargin: \'0px 0px 100px 0px\', // \u63d0\u524d100px\u8fdb\u5165\u89c6\u53e3\u5c31\u5f00\u59cb\u52a0\u8f7d\\r\\n      threshold: 0.1 // \u5f5310%\u7684\u56fe\u7247\u53ef\u89c1\u65f6\u89e6\u53d1\\r\\n    });\\r\\n \\r\\n    // 6. \u5148\u8bbe\u7f6e\u5360\u4f4d\u56fe\uff0c\u5e76\u5f00\u59cb\u89c2\u5bdf\\r\\n    el.src = defaultImage;\\r\\n    observer.observe(el);\\r\\n \\r\\n    // 7. \u5c06observer\u4fdd\u5b58\u5728\u5143\u7d20\u4e0a\uff0c\u4fbf\u4e8e\u5728unmounted\u65f6\u65ad\u5f00\u8fde\u63a5\\r\\n    el._lazyLoadObserver = observer;\\r\\n  },\\r\\n  unmounted(el) {\\r\\n    // \u7ec4\u4ef6\u5378\u8f7d\u65f6\uff0c\u505c\u6b62\u76d1\u542c\uff0c\u9632\u6b62\u5185\u5b58\u6cc4\u6f0f\\r\\n    if (el._lazyLoadObserver) {\\r\\n      el._lazyLoadObserver.disconnect();\\r\\n    }\\r\\n  }\\r\\n};\\r\\n```\\r\\n\\r\\n\\r\\n\\r\\n\u5728\u9879\u76ee\u4e2d\u4f7f\u7528\\r\\n\\r\\n```vue\\r\\n<script setup>\\r\\nconst imgList = [\'/img/img01.jpg\',\\r\\n  \'/img/img02.jpg\',\\r\\n  \'/img/img03.jpg\',\\r\\n  \'/img/img04.jpg\',\\r\\n  \'/img/img05.jpg\',\\r\\n  \'/img/img06.jpg\',\\r\\n  \'/img/img07.jpg\',\\r\\n  \'/img/img08.jpg\',\\r\\n  \'/img/img09.jpg\'\\r\\n]\\r\\n\\r\\n<\/script>\\r\\n\\r\\n<template>\\r\\n  <div v-for=\\"value in imgList\\" :key=\\"value\\">\\r\\n    <img v-lazyload=\\"value\\" :alt=\\"value\\">\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<style scoped>\\r\\ndiv {\\r\\n  display: flex;\\r\\n  flex-direction: column;\\r\\n  justify-content: center;\\r\\n  align-items: center;\\r\\n}\\r\\n\\r\\nimg {\\r\\n  display: block;\\r\\n  width: 800px;\\r\\n  height: 500px;\\r\\n}\\r\\n</style>\\r\\n\\r\\n```\\r\\n\\r\\n\\r\\n\\r\\n## \u6548\u679c\u56fe\\r\\n\\r\\n\u6ca1\u6709\u5c55\u793a\u7684\u56fe\u7247\u6ca1\u6709\u52a0\u8f7d\uff0c\u53ea\u52a0\u8f7d\u89c6\u53e3\u7684\u56fe\u7247\\r\\n\\r\\n![\u6548\u679c\u56fe](./images/\u6548\u679c\u56fe.png)"},{"id":"/2025/03/29/\u5f39\u7a97\u8c03\u7528","metadata":{"permalink":"/blog/2025/03/29/\u5f39\u7a97\u8c03\u7528","source":"@site/blog/2025-03-29/\u5f39\u7a97\u8c03\u7528.md","title":"\u51fd\u6570\u5f0f\u8c03\u7528\u5f39\u7a97\u7ec4\u4ef6","description":"\u4e3a\u4ec0\u4e48\u8981\u4f7f\u7528\u51fd\u6570\u5f0f\u8c03\u7528","date":"2025-03-29T00:00:00.000Z","tags":[],"readingTime":2.53,"hasTruncateMarker":false,"authors":[],"frontMatter":{},"unlisted":false,"prevItem":{"title":"\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b","permalink":"/blog/2025/12/01/\u56fe\u7247\u61d2\u52a0\u8f7d\u5728 Vue \u9879\u76ee\u4e2d\u7684\u901a\u7528\u5c01\u88c5\u4e0e\u53ef\u89c1\u6027\u63a2\u6d4b"},"nextItem":{"title":"Vue3\u6e90\u7801\u89e3\u6790\u4e4bCustomRef","permalink":"/blog/2024/12/30/cunstomRef"}},"content":"## \u4e3a\u4ec0\u4e48\u8981\u4f7f\u7528\u51fd\u6570\u5f0f\u8c03\u7528\\r\\n\\r\\n\u7ec4\u4ef6\u5728\u6ca1\u6709\u4f7f\u7528\u65f6\u4e0d\u4f1a\u6302\u8f7d\uff0c\u4e0d\u4f1a\u5360\u7528\u5185\u5b58\uff0c\u5e76\u4e14\u7236\u7ec4\u4ef6\u4e2d\u6ca1\u6709\u5bf9\u5b50\u7ec4\u4ef6\u7684\u7ef4\u62a4\u903b\u8f91\uff0c\u4ee3\u7801\u66f4\u7b80\u6d01\u3002\\r\\n\\r\\n\u6211\u7684\u60f3\u6cd5\u662f\u7ec4\u4ef6\u53ea\u5728\u9700\u8981\u65f6\u624d\u52a8\u6001\u6302\u8f7d\uff0c\u76f8\u5e94\u903b\u8f91\u90fd\u53ef\u4ee5\u653e\u5728\u51fd\u6570\u4f53\u4e2d\u5904\u7406\u3002\\r\\n\\r\\n\\r\\n\\r\\n## \u5b9e\u73b0\u7684\u601d\u8def\\r\\n\\r\\n\u5199\u4e00\u4e2ahook\u51fd\u6570\uff0c\u4f20\u5165\u7ec4\u4ef6\u53ca\u7ec4\u4ef6\u7684props\uff0c\u52a8\u6001\u6e32\u67d3\u8be5\u7ec4\u4ef6\\r\\n\\r\\n\\r\\n\\r\\n## \u4e3b\u8981\u4ee3\u7801\\r\\n\\r\\n### useComponent.js\\r\\n\\r\\n```javascript\\r\\nimport { createApp } from \\"vue\\";\\r\\nimport ElementPlus from \\"element-plus\\";\\r\\nimport \\"element-plus/dist/index.css\\";\\r\\n\\r\\nconst useComponent = (Component, options) => {\\r\\n  const mountNode = document.createElement(\\"div\\");\\r\\n  document.body.appendChild(mountNode);\\r\\n\\r\\n  return new Promise((resolve, reject) => {\\r\\n    let app = createApp(Component, {\\r\\n      ...options,\\r\\n      close: () => {\\r\\n        app.unmount();\\r\\n        mountNode.remove();\\r\\n        app = undefined;\\r\\n        reject();\\r\\n      },\\r\\n      submit: (list) => {\\r\\n        app.unmount();\\r\\n        mountNode.remove();\\r\\n        app = undefined;\\r\\n        resolve(list);\\r\\n      },\\r\\n    });\\r\\n\\r\\n    if (app) {\\r\\n      app.use(ElementPlus).mount(mountNode);\\r\\n    }\\r\\n  });\\r\\n};\\r\\nexport default useComponent;\\r\\n\\r\\n```\\r\\n\\r\\n### \u4ee3\u7801\u89e3\u91ca\\r\\n\\r\\n\u8fd9\u91cc\u4f7f\u7528createApp\u6765\u521b\u5efa\u4e00\u4e2avue\u5b9e\u4f8b\uff0c\u6240\u4ee5\u5b9e\u9645\u5f00\u53d1\u4e2d\uff0c\u5728main.js\u6587\u4ef6\u5f15\u5165\u7684\u4e09\u65b9\u4ef6\u8fd9\u91cc\u90fd\u8981\u5f15\u5165\u3002\\r\\n\\r\\n\u9996\u5148\u521b\u5efa\u4e00\u4e2adiv\u5143\u7d20\u653e\u5728body\u4e0b\uff0c\u7528\u4e8e\u6302\u8f7d\u7ec4\u4ef6\u3002\u51fd\u6570\u8fd4\u56de\u4e00\u4e2aPromise,\u7528\u4e8e\u56de\u8c03\uff0c\u63a5\u6536\u4e24\u4e2a\u53c2\u6570\uff0c\u7b2c\u4e00\u4e2a\u662f\u7ec4\u4ef6\uff0c\u7b2c\u4e8c\u4e2a\u662f\u7ec4\u4ef6\u7684prop\u3002\\r\\n\\r\\ncreateApp\u51fd\u6570\u9664\u4e86options\u5916\u8fd8\u52a0\u4e86close\u548csubmit,\u7528\u4e8e\u79fb\u9664\u7ec4\u4ef6\uff0c\u987a\u5e8f\u662f\u5148\u5378\u8f7d\uff0c\u7136\u540e\u79fb\u9664div\uff0c\u518d\u7136\u540e\u7f6e\u7a7aapp,\u6700\u540e\u8fdb\u884cresolve\u548creject\u7684\u56de\u8c03\\r\\n\\r\\n\\r\\n\\r\\n## \u5982\u4f55\u4f7f\u7528\\r\\n\\r\\n\u5728\u7236\u7ec4\u4ef6\u4e2d\u5f15\u5165useComponent\u51fd\u6570\\r\\n\\r\\n### App.vue\\r\\n\\r\\n```javascript\\r\\n<template>\\r\\n  <el-button @click=\\"openDialog\\">\u70b9\u51fb\u6253\u5f00\u5f39\u7a97</el-button>\\r\\n</template>\\r\\n\\r\\n<script>\\r\\nimport CustomDialog from \\"./components/CustomDialog.vue\\";\\r\\nimport useComponent from \\"./hooks/useComponent\\";\\r\\n\\r\\nexport default {\\r\\n  name: \\"App\\",\\r\\n  methods: {\\r\\n    openDialog() {\\r\\n      useComponent(CustomDialog, {});\\r\\n    },\\r\\n  },\\r\\n};\\r\\n<\/script>\\r\\n\\r\\n```\\r\\n\\r\\n### CustomDialog.vue\\r\\n\\r\\n```\\r\\n<template>\\r\\n  <el-dialog v-model=\\"visible\\" title=\\"\u81ea\u5b9a\u4e49dialog\\" width=\\"482\\">\\r\\n    <el-form label-position=\\"top\\">\\r\\n      <el-form-item label=\\"\u59d3\u540d\\">\\r\\n        <el-input></el-input>\\r\\n      </el-form-item>\\r\\n      <el-form-item label=\\"\u5e74\u9f84\\">\\r\\n        <el-input></el-input>\\r\\n      </el-form-item>\\r\\n    </el-form>\\r\\n    <template #footer>\\r\\n      <el-button @click=\\"close\\">\u53d6\u6d88</el-button>\\r\\n      <el-button type=\\"primary\\" @click=\\"submit\\">\u786e\u5b9a</el-button>\\r\\n    </template>\\r\\n  </el-dialog>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport { ref, defineExpose, onMounted } from \\"vue\\";\\r\\n\\r\\nconst visible = ref(false);\\r\\n\\r\\nconst open = () => {\\r\\n  visible.value = true;\\r\\n};\\r\\n\\r\\nconst close = () => {\\r\\n  visible.value = false;\\r\\n};\\r\\n\\r\\nconst submit = () => {\\r\\n  new Promise((resolve) => {\\r\\n    setTimeout(() => {\\r\\n      resolve();\\r\\n    }, 1000);\\r\\n  }).then(() => {\\r\\n    console.log(\\"submit success\\");\\r\\n  });\\r\\n};\\r\\n\\r\\nconst init = () => {\\r\\n  open();\\r\\n};\\r\\n\\r\\nonMounted(init);\\r\\n\\r\\ndefineExpose({\\r\\n  open,\\r\\n  close,\\r\\n});\\r\\n<\/script>\\r\\n\\r\\n```\\r\\n\\r\\n### \u5b9e\u73b0\u6548\u679c\\r\\n\\r\\n![\u5f39\u7a97\u5b9e\u73b0](.\\\\images\\\\\u5f39\u7a97\u5b9e\u73b0.jpeg)"},{"id":"/2024/12/30/cunstomRef","metadata":{"permalink":"/blog/2024/12/30/cunstomRef","source":"@site/blog/2024-12-30/cunstomRef.md","title":"Vue3\u6e90\u7801\u89e3\u6790\u4e4bCustomRef","description":"vue3 \u63d0\u4f9b\u7684\u5bf9 Ref \u7684\u81ea\u5b9a\u4e49 api\uff0c\u65b9\u4fbf\u5b9e\u73b0\u5728\u53cc\u5411\u7ed1\u5b9a\u65f6\u8fdb\u884c\u5176\u4ed6\u64cd\u4f5c\u7684\u529f\u80fd","date":"2024-12-30T00:00:00.000Z","tags":[],"readingTime":2.645,"hasTruncateMarker":false,"authors":[],"frontMatter":{},"unlisted":false,"prevItem":{"title":"\u51fd\u6570\u5f0f\u8c03\u7528\u5f39\u7a97\u7ec4\u4ef6","permalink":"/blog/2025/03/29/\u5f39\u7a97\u8c03\u7528"}},"content":"vue3 \u63d0\u4f9b\u7684\u5bf9 Ref \u7684\u81ea\u5b9a\u4e49 api\uff0c\u65b9\u4fbf\u5b9e\u73b0\u5728\u53cc\u5411\u7ed1\u5b9a\u65f6\u8fdb\u884c\u5176\u4ed6\u64cd\u4f5c\u7684\u529f\u80fd\\r\\n\\r\\n\u521b\u5efa\u4e00\u4e2a\u81ea\u5b9a\u4e49\u7684 ref\uff0c\u663e\u5f0f\u58f0\u660e\u5bf9\u5176\u4f9d\u8d56\u8ffd\u8e2a\u548c\u66f4\u65b0\u89e6\u53d1\u7684\u63a7\u5236\u65b9\u5f0f\u3002\\r\\n\\r\\n## \u4ee5\u5e38\u89c1\u7684\u65b9\u5f0f\u5b9e\u73b0\u9632\u6296\\r\\n\\r\\n\u8f93\u5165\u6846\u8f93\u5165\u503c\uff0c\u7ed1\u5b9a input \u65b9\u6cd5\u5bf9 text \u8fdb\u884c\u66f4\u65b0\uff0cinput change \u65b9\u6cd5\u4e2d setTimeout \u5ef6\u65f6 1 \u79d2\u8d4b\u503c\\r\\n\\r\\n```vue\\r\\n<template>\\r\\n  <div>\\r\\n    <input type=\\"text\\" @input=\\"inputChange\\" />\\r\\n    <div>{{ text }}</div>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport { ref } from \\"vue\\";\\r\\n\\r\\nconst text = ref(\\"\\");\\r\\nlet timer;\\r\\n\\r\\nconst inputChange = (e) => {\\r\\n  clearTimeout(timer);\\r\\n  timer = setTimeout(() => {\\r\\n    text.value = e.target.value;\\r\\n  }, 1000);\\r\\n};\\r\\n<\/script>\\r\\n\\r\\n<style lang=\\"scss\\" scoped></style>\\r\\n```\\r\\n\\r\\n\u5982\u679c\u4f7f\u7528 lodash \u7684 debounce \u51fd\u6570\u53ef\u4ee5\u8fd9\u6837\u5b9e\u73b0\\r\\n\\r\\n```vue\\r\\n<template>\\r\\n  <div>\\r\\n    <input type=\\"text\\" @input=\\"debounceInput\\" />\\r\\n    <div>{{ text }}</div>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport { ref } from \\"vue\\";\\r\\nimport { debounce } from \\"lodash\\";\\r\\n\\r\\nconst text = ref(\\"\\");\\r\\n\\r\\nconst inputChange = (e) => {\\r\\n  text.value = e.target.value;\\r\\n};\\r\\n\\r\\nconst debounceInput = debounce(inputChange, 1000);\\r\\n<\/script>\\r\\n\\r\\n<style lang=\\"scss\\" scoped></style>\\r\\n```\\r\\n\\r\\n## \u4ee5\u81ea\u5b9a\u4e49 Ref \u5b9e\u73b0\u9632\u6296\\r\\n\\r\\n```javascript\\r\\n// customRef.js\\r\\nimport { customRef } from \\"vue\\";\\r\\n\\r\\nconst debounceRef = (value, delay = 1000) =>\\r\\n  customRef((track, trigger) => {\\r\\n    let timer;\\r\\n    return {\\r\\n      get() {\\r\\n        track();\\r\\n        return value;\\r\\n      },\\r\\n      set(newValue) {\\r\\n        clearTimeout(timer);\\r\\n        timer = setTimeout(() => {\\r\\n          value = newValue;\\r\\n          trigger();\\r\\n        }, delay);\\r\\n      },\\r\\n    };\\r\\n  });\\r\\n\\r\\nexport default debounceRef;\\r\\n```\\r\\n\\r\\n```\\r\\n// vue\\r\\n<template>\\r\\n  <div>\\r\\n    <input type=\\"text\\" v-model=\\"text\\" />\\r\\n    <div>{{ text }}</div>\\r\\n  </div>\\r\\n</template>\\r\\n\\r\\n<script setup>\\r\\nimport debounceRef from \\"../custom/debounceRef\\";\\r\\n\\r\\nconst text = debounceRef(\\"\\");\\r\\n<\/script>\\r\\n\\r\\n<style lang=\\"scss\\" scoped></style>\\r\\n\\r\\n```\\r\\n\\r\\n\u4ee3\u7801\u89e3\u91ca\uff1a\\r\\n\\r\\ncustomRef \u63a5\u53d7\u4e00\u4e2a\u5de5\u5382\u51fd\u6570\uff0c\u5165\u53c2\u662f trace \u548c trigger\uff0ctrace \u8868\u793a\u6536\u96c6\u53d8\u91cf\u7684\u4f9d\u8d56\uff0ctrigger \u8868\u793a\u89e6\u53d1\u6a21\u677f\u7684\u66f4\u65b0\uff0c\u628a\u4e0a\u9762\u7684\u4ee3\u7801\u62c6\u6210\u4e24\u90e8\u5206\u770b,customRef \u4ee3\u7801\u548c ref \u7684\u903b\u8f91\u57fa\u672c\u4e00\u6837, debounce \u4ee3\u7801\u63a5\u53d7\u4e24\u4e2a\u53c2\u6570 value\uff0cdelay\uff0c\u5728 value \u7684 set \u65b9\u6cd5\u4e2d\u8bbe\u7f6e aetTimeout,\u5ef6\u65f6 delay\uff08ms\uff09\uff0c\u4ece\u800c\u5b9e\u73b0\u9632\u6296\uff0ccustomRef \u7684\u4f7f\u7528\u65b9\u6cd5\u8ddf ref \u4e00\u6837\uff0c\u76f4\u63a5\u4f7f\u7528 v-model \u7ed1\u5b9a customeRef \u5c31\u53ef\u4ee5,\u51cf\u5c11\u4e86\u4ee3\u7801\u91cf\u3002\\r\\n\\r\\n```javascript\\r\\ncustomRef((track, trigger) => {\\r\\n  return {\\r\\n    get value() {\\r\\n      // \u4f9d\u8d56\u6536\u96c6\\r\\n      track();\\r\\n      return value;\\r\\n    },\\r\\n    set value(newValue) {\\r\\n      value = newValue;\\r\\n      // \u89e6\u53d1\u66f4\u65b0\\r\\n      trigger();\\r\\n    },\\r\\n  };\\r\\n});\\r\\n```\\r\\n\\r\\n## \u603b\u7ed3\\r\\n\\r\\ncustomeRef \u672c\u8d28\u4e0a\u662f\u5bf9 trace\uff0ctrigger \u4e24\u4e2a\u65b9\u6cd5\u7684\u8c03\u7528\u65f6\u673a\u81ea\u5b9a\u4e49\uff0c\u5bf9 trigger \u5ef6\u65f6\u66f4\u65b0\u5c31\u662f\u9632\u6296\uff0c\u5982\u679c\u4e0d\u5bf9 trace \u548c trigger \u4fee\u6539\uff0c\u6548\u679c\u5c31\u548c ref \u662f\u4e00\u6837\u7684\u3002\u901a\u8fc7 customRef,\u53ef\u4ee5\u5bf9\u5f88\u591a\u91cd\u590d\u7684\u4ee3\u7801\u8fdb\u884c\u590d\u7528\uff0c\u51cf\u5c11\u4ee3\u7801\u7ef4\u62a4\u3002"}]}}')}}]);